mapper.select:
SELECT COUNT(*) AS total_order_count,
COALESCE( SUM( CASE WHEN ro.status = 'DELIVERED' THEN 1 ELSE 0 END ), 0 ) AS completed_order_count,
COALESCE( SUM( CASE WHEN ro.status = 'CANCELED' THEN 1 ELSE 0 END ), 0 ) AS canceled_order_count,
COALESCE( SUM(ro.gross_order_amount), 0 ) AS gross_order_amount,
COALESCE( SUM(ro.customer_paid_amount), 0 ) AS customer_paid_amount,
COALESCE( ( SELECT SUM(rc.amount) FROM report_order_charges rc INNER JOIN report_orders charge_order ON charge_order.order_id = rc.order_id WHERE charge_order.store_id = #{storeId}
AND charge_order.ordered_at >= #{from}
AND charge_order.ordered_at <= #{to}
), 0 ) AS provider_charge_amount,
COALESCE( ( SELECT SUM( ri.menu_cost * ri.quantity ) FROM report_order_items ri INNER JOIN report_orders item_order ON item_order.order_id = ri.order_id WHERE item_order.store_id = #{storeId}
AND item_order.ordered_at >= #{from}
AND item_order.ordered_at <= #{to}
), 0 ) AS estimated_menu_cost,
COALESCE( ( SELECT SUM( ri.packaging_cost * ri.quantity ) FROM report_order_items ri INNER JOIN report_orders item_order ON item_order.order_id = ri.order_id WHERE item_order.store_id = #{storeId}
AND item_order.ordered_at >= #{from}
AND item_order.ordered_at <= #{to}
), 0 ) AS estimated_packaging_cost
FROM report_orders ro
WHERE ro.store_id = #{storeId}
AND ro.ordered_at >= #{from}
AND ro.ordered_at <= #{to}

SELECT DISTINCT provider_financial_data_status
FROM report_orders
WHERE store_id = #{storeId}
AND provider_financial_data_status IS NOT NULL
AND ordered_at >= #{from}
AND ordered_at <= #{to}
ORDER BY provider_financial_data_status
